67: function buildRecallDelivery(
68:   queryMode: QueryMode,
69:   storeIsEmpty: boolean,
70:   repeatRecall: boolean,
71: ): string | null {
72:   if (queryMode === "soft_recall") {
73:     return "Doc is asking about something you two already talked about. Answer him normally, from what is above and from this thread. If it is not there, say that plainly instead of reconstructing something plausible.";
